  constructor(status: number, body: unknown) {
    const parsed = apiErrorFromPayload(status, body);
    super(
      parsed.status,
      parsed.message,
      {
        code: parsed.code,
        connect_url: parsed.connectUrl,
        manage_url: parsed.manageUrl,
      },
    );
    this.body = body;
    this.name = "RunnerRpcError";
  }
}

export interface RunnerClientDependencies {
  createKeypair(): Promise<NoiseIkKeypair>;
  createInitiator(options: {
