}

async function exchangeEncryptedFrame(
  socket: WebSocket,
  initiator: NoiseIkInitiator,
  plaintext: Uint8Array,
): Promise<Uint8Array> {
  const ciphertext = initiator.encrypt(plaintext);
  if (ciphertext.length > NOISE_CIPHERTEXT_BYTES_MAX) {
