        bytes(
            (
                _MESSAGE_HISTORY_CURSOR_VERSION,
                len(created_at_bytes),
            )
        )
        + created_at_bytes
        + message_id_bytes
    )
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii")


