export const HISTORY_CACHE_PROTOCOL_VERSION = 1 as const;
export const HISTORY_CACHE_TTL_MS = 10 * 60 * 1_000;
export const HISTORY_CACHE_MAX_ENTRIES = 8;
export const HISTORY_CACHE_MAX_ENTRY_BYTES = 1_024 * 1_024;
export const HISTORY_CACHE_MAX_TOTAL_BYTES = 4 * 1_024 * 1_024;

const SESSION_ID_PATTERN = /^[0-9a-f]{32}$/u;
const REQUEST_ID_PATTERN = /^[A-Za-z0-9_-]{1,64}$/u;

interface CacheEntry {
  envelopes: unknown[];
  bytes: number;
  expiresAt: number;
  lastUsed: number;
}

interface StoreOptions {
  now?: () => number;
  maxEntries?: number;
  maxEntryBytes?: number;
  maxTotalBytes?: number;
}

function exactKeys(value: Record<string, unknown>, keys: string[]): boolean {
  const actual = Object.keys(value).sort();
  const expected = [...keys].sort();
  return (
    actual.length === expected.length &&
    actual.every((key, index) => key === expected[index])
  );
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function validIdentity(value: Record<string, unknown>): boolean {
  return (
    value.version === HISTORY_CACHE_PROTOCOL_VERSION &&
    typeof value.requestId === "string" &&
    REQUEST_ID_PATTERN.test(value.requestId) &&
    typeof value.userId === "string" &&
    value.userId.length >= 1 &&
    value.userId.length <= 256 &&
    typeof value.sessionId === "string" &&
    SESSION_ID_PATTERN.test(value.sessionId)
  );
}

function responseBase(request: Record<string, unknown>) {
  return {
    version: HISTORY_CACHE_PROTOCOL_VERSION,
    requestId: request.requestId as string,
  };
}

export class HistoryCacheStore {
  private readonly entries = new Map<string, CacheEntry>();
  private readonly now: () => number;
  private readonly maxEntries: number;
  private readonly maxEntryBytes: number;
  private readonly maxTotalBytes: number;
  private sequence = 0;
  totalBytes = 0;

  constructor(options: StoreOptions = {}) {
    this.now = options.now ?? Date.now;
    this.maxEntries = options.maxEntries ?? HISTORY_CACHE_MAX_ENTRIES;
    this.maxEntryBytes = options.maxEntryBytes ?? HISTORY_CACHE_MAX_ENTRY_BYTES;
    this.maxTotalBytes = options.maxTotalBytes ?? HISTORY_CACHE_MAX_TOTAL_BYTES;
  }

  private key(userId: string, sessionId: string): string {
    return `${userId.length}:${userId}${sessionId}`;
  }

  private purgeExpired(): void {
    const now = this.now();
    for (const [key, entry] of this.entries) {
      if (entry.expiresAt <= now) this.remove(key);
    }
  }

  private remove(key: string): void {
    const entry = this.entries.get(key);
    if (!entry) return;
    this.totalBytes -= entry.bytes;
    this.entries.delete(key);
  }

  get(userId: string, sessionId: string): unknown[] | null {
    this.purgeExpired();
    const entry = this.entries.get(this.key(userId, sessionId));
    if (!entry) return null;
    entry.lastUsed = ++this.sequence;
    return structuredClone(entry.envelopes);
  }

  put(userId: string, sessionId: string, envelopes: unknown[]): boolean {
    let serialized: string;
    try {
      serialized = JSON.stringify(envelopes);
    } catch {
      return false;
    }
    const bytes = new TextEncoder().encode(serialized).byteLength;
    if (bytes > this.maxEntryBytes || bytes > this.maxTotalBytes) return false;
    let copy: unknown[];
    try {
      copy = JSON.parse(serialized) as unknown[];
    } catch {
      return false;
    }
    this.purgeExpired();
    const key = this.key(userId, sessionId);
    this.remove(key);
    this.entries.set(key, {
      envelopes: copy,
      bytes,
      expiresAt: this.now() + HISTORY_CACHE_TTL_MS,
      lastUsed: ++this.sequence,
    });
    this.totalBytes += bytes;
    while (
      this.entries.size > this.maxEntries ||
      this.totalBytes > this.maxTotalBytes
    ) {
      let oldestKey: string | null = null;
      let oldestUse = Number.POSITIVE_INFINITY;
      for (const [candidateKey, entry] of this.entries) {
        if (entry.lastUsed < oldestUse) {
          oldestKey = candidateKey;
          oldestUse = entry.lastUsed;
        }
      }
      if (oldestKey === null) break;
      this.remove(oldestKey);
    }
    return this.entries.has(key);
  }

  delete(userId: string, sessionId: string): void {
    this.remove(this.key(userId, sessionId));
  }
}

export function processHistoryCacheRequest(
  store: HistoryCacheStore,
  value: unknown,
): Record<string, unknown> | null {
  if (
    !isRecord(value) ||
    typeof value.type !== "string" ||
    !validIdentity(value)
  )
    return null;
  const baseKeys = ["version", "type", "requestId", "userId", "sessionId"];
  if (value.type === "get") {
    if (!exactKeys(value, baseKeys)) return null;
    const envelopes = store.get(
      value.userId as string,
      value.sessionId as string,
    );
    return envelopes === null
      ? { ...responseBase(value), ok: true, hit: false }
      : { ...responseBase(value), ok: true, hit: true, envelopes };
  }
  if (value.type === "put") {
    if (
      !exactKeys(value, [...baseKeys, "envelopes"]) ||
      !Array.isArray(value.envelopes)
    )
      return null;
    if (
      !store.put(
        value.userId as string,
        value.sessionId as string,
        value.envelopes,
      )
    )
      return null;
    return { ...responseBase(value), ok: true };
  }
  if (value.type === "delete") {
    if (!exactKeys(value, baseKeys)) return null;
    store.delete(value.userId as string, value.sessionId as string);
    return { ...responseBase(value), ok: true };
  }
  return null;
}

import { HISTORY_CACHE_PROTOCOL_VERSION } from "./sessionHistoryCacheCore";

const REQUEST_TIMEOUT_MS = 250;
const MAX_PENDING_REQUESTS = 32;
const REQUEST_ID_PATTERN = /^[A-Za-z0-9_-]{1,64}$/u;

type Operation = "get" | "put" | "delete";
interface PendingRequest {
  operation: Operation;
  timeout: ReturnType<typeof setTimeout>;
  resolve: (value: unknown[] | null) => void;
}
interface WorkerLike {
  port: MessagePort;
}
type WorkerFactory = () => WorkerLike;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
function exactKeys(
  value: Record<string, unknown>,
  expected: string[],
): boolean {
  const actual = Object.keys(value).sort();
  const keys = [...expected].sort();
  return (
    actual.length === keys.length &&
    actual.every((key, index) => key === keys[index])
  );
}

export class SessionHistoryCacheClient {
  private port: MessagePort | null = null;
  private unavailable = false;
  private disposed = false;
  private counter = 0;
  private readonly pending = new Map<string, PendingRequest>();

  constructor(private readonly workerFactory: WorkerFactory) {}

  private ensurePort(): MessagePort | null {
    if (this.disposed || this.unavailable) return null;
    if (this.port) return this.port;
    try {
      const port = this.workerFactory().port;
      port.onmessage = (event) => this.receive(event.data);
      port.onmessageerror = () => this.failAll();
      port.start();
      this.port = port;
      return port;
    } catch {
      this.unavailable = true;
      return null;
    }
  }

  private failAll(): void {
    for (const [requestId, request] of this.pending) {
      clearTimeout(request.timeout);
      this.pending.delete(requestId);
      request.resolve(null);
    }
  }

  private receive(value: unknown): void {
    if (
      !isRecord(value) ||
      value.version !== HISTORY_CACHE_PROTOCOL_VERSION ||
      typeof value.requestId !== "string"
    )
      return;
    const pending = this.pending.get(value.requestId);
    if (!pending) return;
    this.pending.delete(value.requestId);
    clearTimeout(pending.timeout);
    if (pending.operation === "get") {
      if (
        exactKeys(value, ["version", "requestId", "ok", "hit"]) &&
        value.ok === true &&
        value.hit === false
      ) {
        pending.resolve(null);
        return;
      }
      if (
        exactKeys(value, ["version", "requestId", "ok", "hit", "envelopes"]) &&
        value.ok === true &&
        value.hit === true &&
        Array.isArray(value.envelopes)
      ) {
        pending.resolve(value.envelopes);
        return;
      }
      pending.resolve(null);
      return;
    }
    pending.resolve(
      exactKeys(value, ["version", "requestId", "ok"]) && value.ok === true
        ? []
        : null,
    );
  }

  private request(
    operation: Operation,
    userId: string,
    sessionId: string,
    envelopes?: unknown[],
  ): Promise<unknown[] | null> {
    const port = this.ensurePort();
    if (!port || this.pending.size >= MAX_PENDING_REQUESTS)
      return Promise.resolve(null);
    const requestId = `cache-${Date.now().toString(36)}-${(++this.counter).toString(36)}`;
    if (!REQUEST_ID_PATTERN.test(requestId)) return Promise.resolve(null);
    return new Promise((resolve) => {
      const timeout = setTimeout(() => {
        if (!this.pending.delete(requestId)) return;
        resolve(null);
      }, REQUEST_TIMEOUT_MS);
      this.pending.set(requestId, { operation, timeout, resolve });
      try {
        port.postMessage({
          version: HISTORY_CACHE_PROTOCOL_VERSION,
          type: operation,
          requestId,
          userId,
          sessionId,
          ...(operation === "put" ? { envelopes } : {}),
        });
      } catch {
        clearTimeout(timeout);
        this.pending.delete(requestId);
        resolve(null);
      }
    });
  }

  async get(userId: string, sessionId: string): Promise<unknown[] | null> {
    return this.request("get", userId, sessionId);
  }
  async put(
    userId: string,
    sessionId: string,
    envelopes: unknown[],
  ): Promise<void> {
    await this.request("put", userId, sessionId, envelopes);
  }
  async delete(userId: string, sessionId: string): Promise<void> {
    await this.request("delete", userId, sessionId);
  }
  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.failAll();
    this.port?.close();
    this.port = null;
  }
}

let sharedClient: SessionHistoryCacheClient | null | undefined;

export function getSessionHistoryCacheClient(): SessionHistoryCacheClient | null {
  if (sharedClient !== undefined) return sharedClient;
  if (
    typeof window === "undefined" ||
    typeof SharedWorker !== "function" ||
    window.yinshiDesktop !== undefined
  ) {
    sharedClient = null;
    return null;
  }
  sharedClient = new SessionHistoryCacheClient(
    () =>
      new SharedWorker(
        new URL("./sessionHistoryCache.shared-worker.ts", import.meta.url),
        { type: "module", name: "managed-session-history-v1" },
      ),
  );
  return sharedClient;
}

/// <reference lib="webworker" />

import {
  HistoryCacheStore,
  processHistoryCacheRequest,
} from "./sessionHistoryCacheCore";

const store = new HistoryCacheStore();
const workerScope = self as unknown as SharedWorkerGlobalScope;

workerScope.onconnect = (event: MessageEvent) => {
  const port = event.ports[0];
  if (!port) return;
  port.onmessage = (message) => {
    const response = processHistoryCacheRequest(store, message.data);
    if (response !== null) port.postMessage(response);
  };
  port.start();
};

